    // Mobile nav toggle
    const navToggle = document.querySelector('[data-nav-toggle]');
    const navMenu = document.querySelector('.nav-primary');
    if (navToggle) {
      navToggle.addEventListener('click', () => {
        const open = navMenu.classList.toggle('open');
        navToggle.setAttribute('aria-expanded', String(open));
      });
    }

    // Smooth scroll for in-page anchors
    document.addEventListener('click', (e) => {
      const a = e.target.closest('a[href^="#"]');
      if (!a) return;
      const id = a.getAttribute('href');
      if (id.length > 1) {
        const el = document.querySelector(id);
        if (el) {
          e.preventDefault();
          el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }
    });

    // Newsletter validation hints
    const nlForm = document.getElementById('newsletter');
    const nlEmail = document.getElementById('nl-email');
    const nlHint = document.getElementById('nl-hint');
    nlForm?.addEventListener('submit', (e) => {
      nlHint.textContent = '';
      if (!nlEmail.checkValidity()) {
        e.preventDefault();
        nlHint.textContent = 'Please enter a valid email address.';
        nlEmail.focus();
      } else {
        e.preventDefault();
        nlHint.textContent = 'Thanks! The guide will arrive shortly.';
        nlForm.reset();
